/**
 * Eager English restore (EnglishFreezePrefixes.swift): raw prefixes, sorted, at which an
 * English word freezes with marks on screen. Binary search IN the constant string —
 * no set is built, nothing allocated; probed once per word at the freeze moment.
 */
internal object EnglishFreezePrefixes {
    const val minLength = 4
    const val maxLength = 9
    const val count = 1014
    private fun isSep(c: Char) = c == ' ' || c == '\n'
    /** raw[0 until n] (ascii codes, any case) is in the table. */
    fun contains(raw: IntArray, n: Int): Boolean {
        if (n < minLength || n > maxLength || n > raw.size) return false
        val buf = DATA
        var lo = 0
        var hi = buf.length
        while (lo < hi) {
            var s = (lo + hi) / 2
            while (s > lo && !isSep(buf[s - 1])) s--
            if (isSep(buf[s])) {
                var t = s
                while (t < hi && isSep(buf[t])) t++
                if (t >= hi) { hi = s; continue }
                s = t
            }
            var e = s
            while (e < buf.length && !isSep(buf[e])) e++
            var cmp = 0
            var i = 0
            while (i < n && s + i < e) {
                var k = raw[i]
                if (k in 0x41..0x5A) k = k or 0x20
                val b = buf[s + i].code
                if (b != k) { cmp = if (b < k) -1 else 1; break }
                i++
            }
            if (cmp == 0) {
                val tl = e - s
                if (tl == n) return true
                cmp = if (tl < n) -1 else 1
            }
            if (cmp < 0) lo = e else hi = s
        }
        return false
    }
