/**
 * English vs Vietnamese frequency (EnglishFrequency.swift, Scripts/gen-english-frequency.py):
 * both on ONE log scale 0–255 (10× ≈ 45), plus frequent Vietnamese syllable pairs. Statistics
 * derived from CC BY-SA 4.0 / CC BY 3.0 / CC BY 2.0 FR data — attribution: docs/DATA-SOURCES.md.
 * Binary search IN the constant strings (no set built, nothing allocated); boundary-only.
 */
internal object EnglishFrequency {
    const val strongMin = 150
    const val maxWordLength = 14
    const val maxPairLength = 15
    const val wordCount = 1585
    const val pairCount = 699
    /** Packed scores: English frequency. */
    fun en(packed: Int): Int = packed ushr 8
    /** Packed scores: Vietnamese frequency (0 = no Vietnamese reading). */
    fun vn(packed: Int): Int = packed and 0xFF
    /** (en shl 8 or vn) of lowercase a–z key[0 until n], or -1 if absent. */
    fun scores(key: IntArray, n: Int): Int {
        if (n < 1 || n > maxWordLength || n > key.size) return -1
        val s = find(WORDS, n, '=') { key[it] }
        return if (s < 0) -1 else packed(s + n + 1)
    }
    /** Same for a lowercase word. */
    fun scores(w: String): Int {
        val n = w.length
        if (n < 1 || n > maxWordLength) return -1
        val s = find(WORDS, n, '=') { w[it].code }
        return if (s < 0) -1 else packed(s + n + 1)
    }
    /** "english>telexKey" key[0 until n] (">" included) is in PAIRS. */
    fun hasPair(key: IntArray, n: Int): Boolean {
        if (n < 3 || n > maxPairLength || n > key.size) return false
        return find(PAIRS, n, ' ') { key[it] } >= 0
    }
    private fun nib(c: Char): Int = if (c <= '9') c - '0' else c - 'a' + 10
    private fun packed(i: Int): Int =
        ((nib(WORDS[i]) shl 4 or nib(WORDS[i + 1])) shl 8) or (nib(WORDS[i + 2]) shl 4 or nib(WORDS[i + 3]))
    private fun isSep(c: Char) = c == ' ' || c == '\n'
    /** Start of the token whose head (up to [sep]; whole token when sep = ' ') equals key[0 until n], or -1. */
    private inline fun find(buf: String, n: Int, sep: Char, key: (Int) -> Int): Int {
        var lo = 0
        var hi = buf.length
        while (lo < hi) {
            var s = (lo + hi) / 2
            while (s > lo && !isSep(buf[s - 1])) s--
            if (isSep(buf[s])) {
                var t = s
                while (t < hi && isSep(buf[t])) t++
                if (t >= hi) { hi = s; continue }
                s = t
            }
            var e = s
            while (e < buf.length && !isSep(buf[e])) e++
            var k = e
            if (sep != ' ') { k = s; while (k < e && buf[k] != sep) k++ }
            var cmp = 0
            var i = 0
            while (i < n && s + i < k) {
                val a = buf[s + i].code
                val b = key(i)
                if (a != b) { cmp = if (a < b) -1 else 1; break }
                i++
            }
            if (cmp == 0) {
                val tl = k - s
                if (tl == n) return s
                cmp = if (tl < n) -1 else 1
            }
            if (cmp < 0) lo = e else hi = s
        }
        return -1
    }
