internal fun parseWords(list: String): HashSet<String> {
    val set = HashSet<String>(1024)
    var i = 0
    val n = list.length
    while (i < n) {
        while (i < n && (list[i] == ' ' || list[i] == '\n')) i++
        val s = i
        while (i < n && list[i] != ' ' && list[i] != '\n') i++
        if (i > s) set.add(list.substring(s, i))
    }
    return set
}
